### Link to the code that reproduces this issue or a replay of the bug

https://github.com/vercel/next.js/blob/a3d5a855eb979a536e25884fd2189fa66050b8a6/packages/next/src/server/next-server.ts#L976

### To Reproduce

1. clone https://github.com/gudvinga/next-13-4-custom-router-issue
2. install ```dependencies yarn```
3. build app ```next build```
4. run prod ```NODE_ENV=production node server.js```
5. http://localhost:3000/a -- error on the server

### Describe the Bug

**Can't use Next.js with a custom server when using Page Router and getInitialProps in production mode**
Custom server
```
const { createServer } = require("http");
const { parse } = require("url");
const next = require("next");

const dev = process.env.NODE_ENV !== "production";
const hostname = "localhost";
const port = 3000;
// when using middleware `hostname` and `port` must be provided below
const app = next({ dev, hostname, port });
const handle = app.getRequestHandler();

app.prepare().then(() => {
  createServer(async (req, res) => {
    try {
      // Be sure to pass `true` as the second argument to `url.parse`.
      // This tells it to parse the query portion of the URL.
      const parsedUrl = parse(req.url, true);
      const { pathname, query } = parsedUrl;

      if (pathname === "/a") {
        await app.render(req, res, "/a", query);
      } else {
        await handle(req, res, parsedUrl);
      }
    } catch (err) {
      console.error("Error occurred handling", req.url, err);
      res.statusCode = 500;
      res.end("internal server error");
    }
  })
    .once("error", (err) => {
      console.error(err);
      process.exit(1);
    })
    .listen(port, () => {
      console.log(`> Ready on http://${hostname}:${port}`);
    });
});
```
When I try to run application on Production and open **a page** I get an error **Error: Invariant: render should have used routeModule**

```
Error: Invariant: render should have used routeModule
    at NextNodeServer.renderHTMLImpl (***node_modules/next/dist/server/next-server.js:698:15)
    at ***node_modules/next/dist/server/next-server.js:686:105
    at NextTracerImpl.trace (***node_modules/next/dist/server/lib/trace/tracer.js:90:20)
    at NextNodeServer.renderHTML (***node_modules/next/dist/server/next-server.js:686:41)
    at doRender (***node_modules/next/dist/server/base-server.js:1059:37)
    at cacheEntry.responseCache.get.incrementalCache.incrementalCache (***node_modules/next/dist/server/base-server.js:1197:34)
    at ***node_modules/next/dist/server/response-cache/index.js:99:42
    at ResponseCache.get (***node_modules/next/dist/server/response-cache/index.js:149:11)
    at NextNodeServer.renderToResponseWithComponentsImpl (***node_modules/next/dist/server/base-server.js:1116:53)
    at ***node_modules/next/dist/server/base-server.js:723:121
```
Without getInitialProp works as expected
Looks like here renderHTMLImpl doesn't work with Page Routing https://github.com/vercel/next.js/blob/a3d5a855eb979a536e25884fd2189fa66050b8a6/packages/next/src/server/next-server.ts#L963
```
      } else {
        // If we didn't match a page, we should fallback to using the legacy
        // render method.
        result = await this.renderHTML(req, res, pathname, query, renderOpts)
      }
```
^^ but it doesn't work
https://github.com/vercel/next.js/blob/a3d5a855eb979a536e25884fd2189fa66050b8a6/packages/next/src/server/base-server.ts#L1798

### Expected Behavior

The application must work with getInitialProps and a custom server using Page Routing.


